peerSolutions.content:
After walking to the last node, its `prev` pointer gives the new tail immediately. This avoids searching again from the head. There are two cases: either the tail is the head, or the previous node needs its `next` link cleared.

The empty list and the one-node list both return `null`.

```javascript
/**
 * // Definition for a Node.
 * function ListNode(data, prev, next) {
 *    this.data = data;
 *    this.prev = prev || null;
 *    this.next = next || null;
 * };
 */

class Solution {
  /**
   *
   * @param ListNode head
   * @returns ListNode
   */
  deleteTail(head) {
    if (head === null) {
      return null;
    }

    let tail = head;
    while (tail.next !== null) {
      tail = tail.next;
    }

    if (tail === head) {
      return null;
    }

    const newTail = tail.prev;
    newTail.next = null;
    return head;
  }
}
```

Time complexity: `O(n)` for the walk to the tail.
Space complexity: `O(1)`.

This version first counts the nodes, then walks to the node just before the tail. It makes the position being changed clear, although it scans part of the list twice.

For a list with one node, the method returns `null`. In a list with at least two nodes, the node at position `length - 2` becomes the new tail.

Dry run with `5 <-> 8 <-> 11 <-> 14`: the count is 4, so the code stops at `11` and sets `11.next` to `null`. The result ends at `11`.

```csharp
/*
// Definition for a Node.
public class ListNode {
    public int data;
    public ListNode prev;
    public ListNode next;
    public ListNode();
    public ListNode(int data);
    public ListNode(int data, ListNode prev, ListNode next);
}
*/

public class Solution {
    public ListNode DeleteTail(ListNode head) {
        if (head == null || head.next == null) {
            return null;
        }

        int length = 0;
        ListNode current = head;
        while (current != null) {
            length++;
            current = current.next;
        }

        current = head;
        for (int index = 1; index < length - 1; index++) {
            current = current.next;
        }

        ListNode tail = current.next;
        current.next = null;

        if (tail != null) {
            tail.prev = null;
        }

        return head;
    }
}
```

Time complexity: `O(n)`, including the count pass and the second walk.
Space complexity: `O(1)`. Important edge cases, an empty list and a single-node list, are handled before the traversal.

A single pass is enough if two pointers are kept: `current` moves through the list and `previous` stays one node behind it. When `current` becomes the tail, `previous` is the node that must become the new tail.

### Small dry run
For `4 <-> 7 <-> 9`, the pointers finish with `previous = 7` and `current = 9`. Setting `previous.next` to `null` leaves `4 <-> 7`.

```java
/*
// Definition for a Node.
class ListNode {
    public int data;
    public ListNode prev;
    public ListNode next;
    public ListNode();
    public ListNode(int data);
    public ListNode(int data, ListNode prev, ListNode next);
};
*/

class Solution {
    public ListNode deleteTail(ListNode head) {
        if (head == null || head.next == null) {
            return null;
        }

        ListNode previous = null;
        ListNode current = head;

        while (current.next != null) {
            previous = current;
            current = current.next;
        }

        previous.next = null;
        return head;
    }
}
```

Time complexity: `O(n)`.
Space complexity: `O(1)`. The `prev` link of the remaining nodes is unchanged.

The tail is the only node that needs to be removed. First move to the last node, then connect its previous node to `nullptr`. If the list has one node, the new head is simply `nullptr`.

This changes the links in the original list, but it does not create a new list.

```cpp
/**
class ListNode
{
 * Definition for doubly-linked list.
 *  public:
 *      int data;
 *      ListNode *prev;
 *      ListNode *next;
 *      ListNode() : data(0), prev(nullptr), next(nullptr) {}
 *      ListNode(int x) : data(x), prev(nullptr), next(nullptr) {}
 *      ListNode(int x, ListNode *prev, ListNode *next) : data(x), prev(prev), next(next) {}
};
*/

class Solution {
public:
    ListNode *deleteTail(ListNode *&head) {
        if (head == nullptr) {
            return nullptr;
        }

        if (head->next == nullptr) {
            head = nullptr;
            return head;
        }

        ListNode* tail = head;
        while (tail->next != nullptr) {
            tail = tail->next;
        }

        ListNode* newTail = tail->prev;
        newTail->next = nullptr;
        head = head;
        return head;
    }
};
```

Time complexity: `O(n)` to reach the last node.
Space complexity: `O(1)`.

